<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue';
import {MessageCircle,LayoutDashboard,Plus,Search,LogOut,Send,Settings2,Smartphone,ShieldCheck,Bot,UserRound,Blend,ChevronDown,RefreshCw,Trash2,X,Menu,CheckCircle2,AlertCircle,Lock,Mail,ArrowRight,Sparkles,Radio,Wifi,Clock,MoreHorizontal} from 'lucide-vue-next';
const API = import.meta.env.VITE_API_URL || (typeof window !== 'undefined' && window.location.hostname ? `${window.location.protocol}//${window.location.hostname}:5888` : 'http://localhost:5888');
const token=ref(localStorage.getItem('autochapp_token')||'');const currentUser=ref(JSON.parse(localStorage.getItem('autochapp_user')||'null'));
const authMode=ref('login'),form=ref({name:'',email:'',password:''}),busy=ref(false),error=ref(''),notice=ref('');
const accounts=ref([]),conversations=ref([]),messages=ref([]),activeAccount=ref(null),activeConversation=ref(null),section=ref('inbox'),query=ref(''),draft=ref(''),showAdd=ref(false),newAccountName=ref(''),qrData=ref(null),showSettings=ref(false),settings=ref({}),sidebarMobile=ref(false),bottom=ref(null);
let poll=null;
const filtered= computed(()=>conversations.value.filter(x=>(!activeAccount.value||x.account_id===activeAccount.value.id)&&`${x.title} ${x.jid}`.toLowerCase().includes(query.value.toLowerCase())));
const statusLabel=s=>({connected:'Connecté',connecting:'Connexion...',qr:'Scanner le QR',disconnected:'Hors ligne'})[s]||s;
const modeLabel=s=>({manual:'Manuel',ai:'IA autonome',hybrid:'Hybride'})[s]||s;
async function api(path,opts={}){const r=await fetch(API+path,{...opts,headers:{'Content-Type':'application/json',...(token.value?{'Authorization':'Bearer '+token.value}:{}),...(opts.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||`Erreur HTTP ${r.status}`);return d}
function notify(e){error.value=e.message||String(e);setTimeout(()=>{error.value=''},5500)}
async function authenticate(){busy.value=true;error.value='';try{const path=authMode.value==='login'?'/api/auth/login':'/api/auth/register';const data=await api(path,{method:'POST',body:JSON.stringify(form.value)});setAuth(data)}catch(e){notify(e)}finally{busy.value=false}}
function setAuth(data){token.value=data.token;currentUser.value=data.user;localStorage.setItem('autochapp_token',data.token);localStorage.setItem('autochapp_user',JSON.stringify(data.user));load()}
async function googleCredential(response){try{setAuth(await api('/api/auth/google',{method:'POST',body:JSON.stringify({credential:response.credential})}))}catch(e){notify(e)}}
const GOOGLE_ID=import.meta.env.VITE_GOOGLE_CLIENT_ID||'';
onMounted(()=>{if(token.value)load();if(GOOGLE_ID){const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=true;s.onload=()=>{window.google.accounts.id.initialize({client_id:GOOGLE_ID,callback:googleCredential});window.google.accounts.id.renderButton(document.querySelector('#google-signin'),{theme:'outline',size:'large',width:320})};document.head.appendChild(s)}});
onUnmounted(()=>clearInterval(poll));
function logout(){token.value='';currentUser.value=null;accounts.value=[];conversations.value=[];messages.value=[];activeAccount.value=null;activeConversation.value=null;localStorage.removeItem('autochapp_token');localStorage.removeItem('autochapp_user');clearInterval(poll)}
async function load(){try{const [a,c]=await Promise.all([api('/api/accounts'),api('/api/conversations')]);accounts.value=a.accounts;conversations.value=c.conversations;if(!activeAccount.value&&accounts.value.length)activeAccount.value=accounts.value[0];if(activeAccount.value)activeAccount.value=accounts.value.find(x=>x.id===activeAccount.value.id)||accounts.value[0]||null;if(activeConversation.value){activeConversation.value=conversations.value.find(c=>c.id===activeConversation.value.id)||null;if(activeConversation.value)await loadMessages()}clearInterval(poll);poll=setInterval(refresh,4500)}catch(e){notify(e)}}
async function refresh(){if(!token.value)return;try{const [a,c]=await Promise.all([api('/api/accounts'),api('/api/conversations')]);accounts.value=a.accounts;conversations.value=c.conversations;if(activeAccount.value)activeAccount.value=accounts.value.find(x=>x.id===activeAccount.value.id)||null;if(activeConversation.value){activeConversation.value=conversations.value.find(x=>x.id===activeConversation.value.id)||null;if(activeConversation.value)await loadMessages()}if(qrData.value&&qrData.value.id){const s=await api(`/api/accounts/${qrData.value.id}/status`);qrData.value={...qrData.value,...s};if(s.status==='connected'){qrData.value=null;await load()}}}catch{}}
async function addAccount(){if(!newAccountName.value.trim())return;busy.value=true;try{const data=await api('/api/accounts',{method:'POST',body:JSON.stringify({label:newAccountName.value})});showAdd.value=false;newAccountName.value='';await load();await connect(data.account)}catch(e){notify(e)}finally{busy.value=false}}
async function connect(account){try{qrData.value={id:account.id,label:account.label,status:'connecting',qr:null};const d=await api(`/api/accounts/${account.id}/qr`);qrData.value={...qrData.value,...d}}catch(e){notify(e)}}
async function removeAccount(a){if(!confirm(`Supprimer ${a.label} et toutes ses conversations ?`))return;try{await api(`/api/accounts/${a.id}`,{method:'DELETE'});activeAccount.value=null;activeConversation.value=null;await load()}catch(e){notify(e)}}
async function selectConversation(c){activeConversation.value=c;section.value='inbox';sidebarMobile.value=false;showSettings.value=false;await loadMessages()}
async function loadMessages(){if(!activeConversation.value)return;try{const data=await api(`/api/conversations/${activeConversation.value.id}/messages`);const had=messages.value.length;messages.value=data.messages;if(messages.value.length!==had)nextTick(()=>bottom.value?.scrollIntoView({behavior:'smooth'}))}catch{}}
async function send(){if(!draft.value.trim()||!activeConversation.value||busy.value)return;const content=draft.value;draft.value='';busy.value=true;try{await api(`/api/conversations/${activeConversation.value.id}/messages`,{method:'POST',body:JSON.stringify({content})});await loadMessages()}catch(e){draft.value=content;notify(e)}finally{busy.value=false}}
function openSettings(){settings.value={...activeConversation.value};showSettings.value=true}
async function saveSettings(){busy.value=true;try{const d=await api(`/api/conversations/${activeConversation.value.id}/settings`,{method:'PATCH',body:JSON.stringify(settings.value)});activeConversation.value=d.conversation;showSettings.value=false;await load()}catch(e){notify(e)}finally{busy.value=false}}
</script>
<template>
  <div v-if="!token" class="auth-page"><div class="auth-ambient one"></div><div class="auth-ambient two"></div><div class="auth-wrap"><div class="auth-left"><div class="brand brand-auth"><span class="brand-icon"><MessageCircle :size="22" stroke-width="2.5"/></span> auto<span>chapp</span><span class="brand-dot">.</span></div><div class="eyebrow"><Sparkles :size="15"/> LA MESSAGERIE RÉINVENTÉE</div><h1>Une seule interface.<br><span>Toutes vos conversations.</span></h1><p>Unifiez vos comptes WhatsApp et laissez votre assistant IA prendre le relais, quand vous le décidez.</p><div class="auth-features"><div><span><MessageCircle :size="17"/></span> Tous vos messages au même endroit</div><div><span><Bot :size="17"/></span> Des réponses intelligentes et personnalisées</div><div><span><ShieldCheck :size="17"/></span> Vous gardez le contrôle</div></div><div class="auth-caption">Votre équipe, vos clients, votre rythme.</div></div><div class="auth-card"><div class="mini-logo"><span class="brand-icon"><MessageCircle :size="17"/></span> autochapp</div><h2>{{authMode==='login'?'Bon retour parmi nous':'Créez votre espace'}}</h2><p class="muted">{{authMode==='login'?'Connectez-vous pour retrouver vos conversations.':'Commencez à gérer vos messages plus intelligemment.'}}</p><form @submit.prevent="authenticate"><label v-if="authMode==='register'">Votre nom<input v-model="form.name" required placeholder="Ex. Didier Sofo" autocomplete="name"/></label><label>Adresse e-mail<input v-model="form.email" required type="email" placeholder="vous@entreprise.com" autocomplete="email"/></label><label>Mot de passe<input v-model="form.password" required type="password" minlength="8" placeholder="••••••••" :autocomplete="authMode==='login'?'current-password':'new-password'"/></label><button class="btn primary auth-button" :disabled="busy">{{busy?'Chargement…':authMode==='login'?'Se connecter':'Créer mon compte'}} <ArrowRight :size="17"/></button></form><div class="divider-word"><span>OU CONTINUER AVEC</span></div><div v-if="GOOGLE_ID" id="google-signin" class="google-container"></div><p v-else class="oauth-hint">Connexion Google disponible après configuration OAuth.</p><p class="switch-auth">{{authMode==='login'?'Vous êtes nouveau ?':'Déjà un compte ?'}} <button @click="authMode=authMode==='login'?'register':'login'">{{authMode==='login'?'Créer un compte':'Se connecter'}}</button></p><div class="fineprint"><Lock :size="13"/> Authentification sécurisée</div></div></div></div>
  <div v-else class="app-layout"><aside class="sidebar" :class="{'mobile-open':sidebarMobile}"><div class="side-brand"><span class="brand-icon"><MessageCircle :size="21"/></span> auto<span>chapp</span><span class="brand-dot">.</span><button class="close-mobile" @click="sidebarMobile=false"><X :size="20"/></button></div><div class="workspace-label">ESPACE DE TRAVAIL</div><button class="nav-btn" :class="{selected:section==='overview'}" @click="section='overview';sidebarMobile=false"><LayoutDashboard :size="19"/> Vue d'ensemble</button><button class="nav-btn" :class="{selected:section==='inbox'}" @click="section='inbox';sidebarMobile=false"><MessageCircle :size="19"/> Boîte de réception <span class="nav-count">{{conversations.length}}</span></button><div class="side-section-heading"><span>VOS COMPTES</span><button title="Ajouter un compte" @click="showAdd=true"><Plus :size="18"/></button></div><div class="account-list"><button class="account-btn" :class="{picked:!activeAccount}" @click="activeAccount=null;section='inbox'"><span class="account-avatar all"><MessageCircle :size="17"/></span><span>Tous les comptes</span></button><button v-for="a in accounts" :key="a.id" class="account-btn" :class="{picked:activeAccount?.id===a.id}" @click="activeAccount=a;section='inbox'"><span class="account-avatar">{{a.label[0].toUpperCase()}}</span><span class="account-name">{{a.label}}</span><span class="status-dot" :class="a.status"></span></button></div><button class="add-account-link" @click="showAdd=true"><Plus :size="16"/> Connecter un compte</button><div class="side-bottom"><div class="user-chip"><div class="user-avatar">{{currentUser?.name?.[0]?.toUpperCase()}}</div><div><strong>{{currentUser?.name}}</strong><small>Mon espace</small></div><button title="Déconnexion" @click="logout"><LogOut :size="18"/></button></div></div></aside><div v-if="sidebarMobile" class="mobile-mask" @click="sidebarMobile=false"></div>
  <main class="workspace"><header class="topbar"><button class="mobile-menu" @click="sidebarMobile=true"><Menu :size="22"/></button><div class="breadcrumb">Espace de travail <span>/</span> <strong>{{section==='overview'?'Vue d’ensemble':'Messages'}}</strong></div><div class="header-right"><span class="live-chip"><span></span> Espace actif</span><div class="header-avatar">{{currentUser?.name?.[0]?.toUpperCase()}}</div></div></header>
  <section v-if="section==='overview'" class="overview"><div class="page-kicker">VOTRE CENTRE DE COMMANDE</div><h1>Bonjour, {{currentUser?.name?.split(' ')[0]}} <span class="wave">✳</span></h1><p class="muted">Votre activité WhatsApp, en un seul regard.</p><div class="stat-grid"><div class="stat-card"><div class="stat-label">Comptes connectés <Smartphone :size="18"/></div><div class="stat-number">{{accounts.filter(a=>a.status==='connected').length}} <span>/ {{accounts.length}}</span></div><div class="stat-footer">Comptes actifs</div></div><div class="stat-card"><div class="stat-label">Conversations <MessageCircle :size="18"/></div><div class="stat-number">{{conversations.length}}</div><div class="stat-footer">Tous les échanges</div></div><div class="stat-card"><div class="stat-label">Assistées par l'IA <Bot :size="18"/></div><div class="stat-number">{{conversations.filter(c=>c.mode!=='manual').length}}</div><div class="stat-footer">Modes IA et hybride</div></div></div><div class="overview-panels"><div class="overview-panel"><div class="panel-title">Vos comptes <button class="text-action" @click="showAdd=true"><Plus :size="15"/> Ajouter</button></div><div v-if="!accounts.length" class="empty-inline">Vous n'avez pas encore connecté de compte.</div><div v-for="a in accounts" :key="a.id" class="overview-account"><span class="account-avatar">{{a.label[0]}}</span><div class="flex-grow"><strong>{{a.label}}</strong><small>{{a.phone||'Numéro non associé'}}</small></div><span class="status-tag" :class="a.status">{{statusLabel(a.status)}}</span><button class="subtle-icon" @click="connect(a)" title="Connecter / voir QR"><RefreshCw :size="16"/></button><button class="subtle-icon danger" @click="removeAccount(a)" title="Supprimer"><Trash2 :size="16"/></button></div></div><div class="overview-panel accent-panel"><span class="chip"><Sparkles :size="14"/> ASSISTANT INTELLIGENT</span><h2>L’IA répond.<br>Vous décidez.</h2><p>Pour chaque contact, choisissez entre contrôle total, délégation à l’IA ou assistance conditionnelle.</p><button class="btn light" @click="section='inbox'">Ouvrir mes messages <ArrowRight :size="17"/></button></div></div></section>
  <section v-else class="inbox"><div class="chat-list-panel"><div class="list-heading"><div><small>MESSAGERIE UNIFIÉE</small><h2>Conversations <span>{{filtered.length}}</span></h2></div><button class="icon-circle" title="Actualiser" @click="refresh"><RefreshCw :size="17"/></button></div><div class="search-box"><Search :size="17"/><input v-model="query" placeholder="Rechercher un contact…"/></div><div class="account-filter"><span>{{activeAccount?.label||'Tous les comptes'}}</span><ChevronDown :size="15"/></div><div class="conversation-scroll"><button v-for="c in filtered" :key="c.id" class="conversation-item" :class="{active:c.id===activeConversation?.id}" @click="selectConversation(c)"><span class="contact-avatar">{{c.title[0]?.toUpperCase()||'?'}}</span><span class="conv-info"><strong>{{c.title}}</strong><small>{{c.jid.split('@')[0]}}</small></span><span class="mode-mini" :class="c.mode">{{c.mode==='manual'?'MOI':c.mode==='ai'?'IA':'MIX'}}</span></button><div v-if="!filtered.length" class="list-empty"><MessageCircle :size="33"/><strong>Aucune conversation</strong><span>Connectez WhatsApp et recevez un message pour commencer.</span></div></div><button class="connect-banner" @click="showAdd=true"><Plus :size="17"/> Ajouter un compte WhatsApp</button></div>
  <div class="chat-main" v-if="activeConversation"><div class="chat-header"><span class="contact-avatar chat-contact">{{activeConversation.title[0]?.toUpperCase()}}</span><div class="chat-header-info"><strong>{{activeConversation.title}}</strong><small>{{activeConversation.jid.split('@')[0]}}</small></div><span class="mode-pill" :class="activeConversation.mode"><Bot v-if="activeConversation.mode==='ai'" :size="15"/><Blend v-else-if="activeConversation.mode==='hybrid'" :size="15"/><UserRound v-else :size="15"/> {{modeLabel(activeConversation.mode)}}</span><button class="icon-circle" title="Paramètres de l'assistant" @click="openSettings"><Settings2 :size="19"/></button></div><div class="chat-messages"><div class="day-divider"><span>Conversation WhatsApp</span></div><div v-for="m in messages" :key="m.id" class="message-row" :class="m.direction"><div class="bubble"><div>{{m.content}}</div><div class="bubble-meta"><Bot v-if="m.sender==='ai'" :size="12"/>{{m.sender==='ai'?'Assisté IA · ':''}}{{new Date(m.created_at).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}}</div></div></div><div v-if="!messages.length" class="messages-placeholder">Les messages reçus apparaîtront ici.</div><div ref="bottom"></div></div><div class="composer"><div class="composer-hint"><span class="composer-indicator"></span> {{activeConversation.mode==='manual'?'Mode manuel : vous répondez aux messages':activeConversation.mode==='ai'?'Mode IA : les messages entrants peuvent recevoir une réponse automatique':'Mode hybride : les règles déterminent les réponses automatiques'}}</div><form class="composer-box" @submit.prevent="send"><input v-model="draft" placeholder="Écrivez votre message…"/><button :disabled="!draft.trim()||busy" title="Envoyer"><Send :size="18"/></button></form><div class="composer-footnote">Les messages envoyés partent via votre compte WhatsApp connecté.</div></div></div>
  <div v-else class="chat-blank"><div class="blank-icon"><MessageCircle :size="44"/></div><h2>Vos conversations, sans limites.</h2><p>Sélectionnez une conversation pour commencer à échanger ou configurez votre assistant intelligent.</p><button class="btn primary" @click="showAdd=true"><Plus :size="17"/> Connecter WhatsApp</button></div></section></main></div>
  <div v-if="showAdd" class="modal-overlay" @click.self="showAdd=false"><div class="modal small-modal"><div class="modal-top"><div><small>NOUVEAU COMPTE</small><h2>Connecter WhatsApp</h2></div><button @click="showAdd=false"><X :size="20"/></button></div><p class="muted">Donnez un nom à votre compte pour le retrouver facilement.</p><form @submit.prevent="addAccount"><label>Nom du compte<input v-model="newAccountName" required autofocus placeholder="Ex. WhatsApp professionnel"/></label><button class="btn primary full" :disabled="busy">Continuer <ArrowRight :size="17"/></button></form></div></div>
  <div v-if="qrData" class="modal-overlay" @click.self="qrData=null"><div class="modal qr-modal"><div class="modal-top"><div><small>CONNEXION SÉCURISÉE</small><h2>{{qrData.label}}</h2></div><button @click="qrData=null"><X :size="20"/></button></div><div v-if="qrData.status==='connected'" class="qr-success"><CheckCircle2 :size="56"/><h3>Compte connecté !</h3><p>Vos messages pourront apparaître dans votre espace.</p></div><template v-else><div class="qr-frame"><img v-if="qrData.qr" :src="qrData.qr" alt="Code QR WhatsApp à scanner"/><div v-else class="qr-loading"><RefreshCw :size="36" class="spin"/><span>Génération du QR…</span></div></div><p class="qr-instructions">Sur votre téléphone : <strong>WhatsApp → Appareils connectés → Connecter un appareil</strong>, puis scannez ce code.</p><button class="btn secondary full" @click="connect({id:qrData.id,label:qrData.label})"><RefreshCw :size="16"/> Régénérer le QR</button></template></div></div>
  <div v-if="showSettings" class="modal-overlay" @click.self="showSettings=false"><div class="modal settings-modal"><div class="modal-top"><div><small>PERSONNALISATION PAR CONTACT</small><h2>Assistant intelligent</h2><p class="muted">{{activeConversation?.title}}</p></div><button @click="showSettings=false"><X :size="20"/></button></div><div class="settings-body"><label class="field-heading">Mode de conversation</label><div class="mode-options"><button v-for="mode in [{key:'manual',label:'Manuel',description:'Vous répondez',icon:UserRound},{key:'ai',label:'IA',description:'Réponses auto',icon:Bot},{key:'hybrid',label:'Hybride',description:'Selon vos règles',icon:Blend}]" :key="mode.key" class="mode-option" :class="{chosen:settings.mode===mode.key}" @click="settings.mode=mode.key"><component :is="mode.icon" :size="21"/><strong>{{mode.label}}</strong><small>{{mode.description}}</small></button></div><template v-if="settings.mode!=='manual'"><label>Instructions pour l'IA<textarea v-model="settings.instructions" rows="4" placeholder="Ex. Réponds poliment en français. Sois concis. Pour les prix, demande le produit concerné. Ne confirme jamais une commande sans mon accord."></textarea></label><template v-if="settings.mode==='hybrid'"><label>Quand l'IA peut-elle répondre ?<select v-model="settings.hybrid_rule"><option value="keywords">Si le message contient certains mots-clés</option><option value="outside_hours">En dehors des heures de présence (UTC)</option><option value="always_draft">Jamais automatiquement (humain uniquement)</option></select></label><label v-if="settings.hybrid_rule==='keywords'">Mots-clés, séparés par des virgules<input v-model="settings.keywords" placeholder="prix, horaires, disponibilité"/></label><label v-if="settings.hybrid_rule==='outside_hours'">Plage de présence (UTC)<input v-model="settings.business_hours" placeholder="09:00-18:00"/></label></template><label>Délai minimal entre les réponses automatiques (secondes)<input type="number" min="0" max="86400" v-model.number="settings.cooldown_seconds"/></label></template><div class="info-note"><ShieldCheck :size="17"/> Les modes IA et hybride nécessitent une clé de fournisseur IA configurée côté serveur.</div></div><div class="modal-footer"><button class="btn secondary" @click="showSettings=false">Annuler</button><button class="btn primary" :disabled="busy" @click="saveSettings">Enregistrer les préférences</button></div></div></div>
  <div v-if="error" class="toast error"><AlertCircle :size="19"/> {{error}} <button @click="error=''">×</button></div>
</template>
